parameters.jsCode:
const agenda = $node["Definir Agenda"].json;
const eventosRaw = $items("Disponibilidade do Google Calendar").map(item => item.json);
const trigger = $node["trigger"].json || {};

const tz = agenda.timezone || "America/Sao_Paulo";
const intervaloMin = agenda.timeBetweenMeetingsMinutes;
const diasSemana = { DOM: 0, SEG: 1, TER: 2, QUA: 3, QUI: 4, SEX: 5, SAB: 6 };
const nomesDia = ["DOM", "SEG", "TER", "QUA", "QUI", "SEX", "SAB"];

// Quantos dias corridos varrer (o Calendar busca 2 semanas)
const DIAS_A_FRENTE = 14;
// Quantos slots devolver no máximo (evita estourar o prompt do agente)
const MAX_SLOTS = 6;

// Mapa de expressões em linguagem natural -> HH:MM
const MAPA_HORARIO_TEXTO = {
  "manha": "10:00",
  "manhã": "10:00",
  "inicio da manha": "10:00",
  "início da manhã": "10:00",
  "fim da manha": "11:30",
  "fim da manhã": "11:30",
  "meio dia": "11:30",
  "tarde": "14:00",
  "inicio da tarde": "14:00",
  "início da tarde": "14:00",
  "meio da tarde": "15:00",
  "fim da tarde": "16:30",
  "final da tarde": "16:30"
};

// -------------------------
// Normaliza eventos: pega só YYYY-MM-DDTHH:MM
// -------------------------

const eventos = (eventosRaw || [])
  .filter(ev => ev?.start?.dateTime && ev?.end?.dateTime)
  .map(ev => ({
    start: ev.start.dateTime.substring(0, 16),
    end:   ev.end.dateTime.substring(0, 16),
  }));

// -------------------------
// Datas relativas (SP)
// -------------------------

function getDataOffset(dias) {
  const hojeLocalStr = new Date().toLocaleString("sv-SE", { timeZone: tz }).slice(0, 10);
  const d = new Date(hojeLocalStr + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + dias);
  return d.toISOString().slice(0, 10);
}

const hojeStr = getDataOffset(0);
const amanhaStr = getDataOffset(1);
const depoisAmanhaStr = getDataOffset(2);

const agoraSP = new Date().toLocaleString("sv-SE", { timeZone: tz }).slice(11, 16);

// -------------------------
// Helpers
// -------------------------

function somaMinutos(hhmm, min) {
  const [h, m] = hhmm.split(":").map(Number);
  const total = h * 60 + m + min;
  return String(Math.floor(total / 60)).padStart(2, "0") + ":" + String(total % 60).padStart(2, "0");
}

function menorQue(a, b) {
  return a < b;
}

function nomeDiaDaData(dataStr) {
  return nomesDia[new Date(dataStr + "T00:00:00Z").getUTCDay()];
}

// Converte "16:30", "16h30", "16h", "fim da tarde" -> "HH:MM" (ou null)
function normalizaHora(texto) {
  if (!texto) return null;

  const t = String(texto).trim().toLowerCase();

  // Já está em HH:MM
  let m = t.match(/^(\d{1,2}):(\d{2})$/);
  if (m) return String(m[1]).padStart(2, "0") + ":" + m[2];

  // Formatos 16h / 16h30 / 16 h 30
  m = t.match(/^(\d{1,2})\s*h\s*(\d{2})?$/);
  if (m) return String(m[1]).padStart(2, "0") + ":" + (m[2] || "00");

  // Só o número: "16"
  m = t.match(/^(\d{1,2})$/);
  if (m && Number(m[1]) <= 23) return String(m[1]).padStart(2, "0") + ":00";

  // Linguagem natural (sem acento também resolve)
  const semAcento = t.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  for (const chave of Object.keys(MAPA_HORARIO_TEXTO)) {
    const chaveSemAcento = chave.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    if (semAcento === chaveSemAcento || semAcento.includes(chaveSemAcento)) {
      return MAPA_HORARIO_TEXTO[chave];
    }
  }

  return null;
}

// -------------------------
// Geração dos Slots (dias corridos, não só a próxima ocorrência da semana)
// -------------------------

let slotsLivres = [];

for (let i = 0; i < DIAS_A_FRENTE; i++) {
  const dataStr = getDataOffset(i);
  const nomeDia = nomeDiaDaData(dataStr);
  const dia = agenda.schedule.find(d => d.day === nomeDia);

  if (!dia || !dia.available) continue;

  const faixas = Array.isArray(dia.hours) ? dia.hours : [dia.hours];

  for (const faixa of faixas) {
    if (!faixa || !faixa.after || !faixa.before) continue;

    let current = faixa.after;
    const fim = faixa.before;

    while (menorQue(current, fim)) {
      const next = somaMinutos(current, intervaloMin);
      if (next > fim) break;

      const currentDT = `${dataStr}T${current}`;
      const nextDT = `${dataStr}T${next}`;

      // Bloqueia slots passados de hoje (+30 min de margem)
      if (dataStr === hojeStr) {
        const limite = somaMinutos(agoraSP, 30);
        if (menorQue(current, limite)) {
          current = next;
          continue;
        }
      }

      const ocupado = eventos.some(ev => currentDT < ev.end && nextDT > ev.start);

      if (!ocupado) {
        let relative = null;
        if (dataStr === hojeStr) {
          relative = "hoje";
        } else if (dataStr === amanhaStr) {
          relative = "amanha";
        } else if (dataStr === depoisAmanhaStr) {
          relative = "depois_amanha";
        }

        slotsLivres.push({
          day: nomeDia,
          date: dataStr,
          start: currentDT,
          end: nextDT,
          relativeDay: relative,
          isToday: dataStr === hojeStr,
          isTomorrow: dataStr === amanhaStr,
          isDayAfterTomorrow: dataStr === depoisAmanhaStr
        });
      }

      current = next;
    }
  }
}

// Ordena slots pela data/hora real
slotsLivres.sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

const totalSlotsLivres = slotsLivres.length;
slotsLivres = slotsLivres.slice(0, MAX_SLOTS);

// -------------------------
// 🔎 Validação COMPLETA do horário solicitado
// -------------------------

let horarioSolicitadoDisponivel = null;
let motivoIndisponivel = null;
let horarioSolicitadoNormalizado = null;

if (trigger.horario) {

  let dataSolicitada = null;
  let horaSolicitada = null;

  if (String(trigger.horario).includes("T")) {
    // Formato completo: 2026-09-05T19:00
    const bruto = String(trigger.horario).substring(0, 16);
    dataSolicitada = bruto.slice(0, 10);
    horaSolicitada = normalizaHora(bruto.slice(11));
  } else {
    horaSolicitada = normalizaHora(trigger.horario);
    dataSolicitada = trigger.dia || null;
  }

  if (!dataSolicitada || !horaSolicitada) {
    // Não deu para interpretar (ex.: "fim da tarde" sem dia) -> indefinido, não "false"
    horarioSolicitadoDisponivel = null;
    motivoIndisponivel = !horaSolicitada ? "horario_nao_interpretado" : "dia_nao_informado";
  } else {

    horarioSolicitadoNormalizado = `${dataSolicitada}T${horaSolicitada}`;

    const inicioSolicitado = horarioSolicitadoNormalizado;
    const fimSolicitado = dataSolicitada + "T" + somaMinutos(horaSolicitada, intervaloMin);

    // 1️⃣ Dia existe e está disponível na agenda
    const diaSemanaNumero = new Date(dataSolicitada + "T00:00:00Z").getUTCDay();
    const diaAgenda = agenda.schedule.find(d => diasSemana[d.day] === diaSemanaNumero);

    if (!diaAgenda || !diaAgenda.available) {
      horarioSolicitadoDisponivel = false;
      motivoIndisponivel = "dia_nao_disponivel";
    } else {

      const faixas = Array.isArray(diaAgenda.hours) ? diaAgenda.hours : [diaAgenda.hours];

      // 2️⃣ Dentro de alguma faixa permitida
      const dentroDeAlgumaFaixa = faixas.some(faixa =>
        faixa &&
        horaSolicitada >= faixa.after &&
        somaMinutos(horaSolicitada, intervaloMin) <= faixa.before
      );

      if (!dentroDeAlgumaFaixa) {
        horarioSolicitadoDisponivel = false;
        motivoIndisponivel = "fora_do_horario";
      } else {

        // 3️⃣ Conflito com eventos
        const ocupado = eventos.some(ev =>
          inicioSolicitado < ev.end && fimSolicitado > ev.start
        );

        if (ocupado) {
          horarioSolicitadoDisponivel = false;
          motivoIndisponivel = "conflito_evento";
        } else if (dataSolicitada < hojeStr) {
          // 4️⃣ Data no passado
          horarioSolicitadoDisponivel = false;
          motivoIndisponivel = "data_passada";
        } else if (dataSolicitada === hojeStr && horaSolicitada < somaMinutos(agoraSP, 30)) {
          horarioSolicitadoDisponivel = false;
          motivoIndisponivel = "horario_passado";
        } else {
          horarioSolicitadoDisponivel = true;
        }
      }
    }
  }
}

// -------------------------
// Output final
// -------------------------

return [{
  slotsLivres,
  totalSlotsLivres,
  horarioSolicitado: trigger.horario || null,
  horarioSolicitadoNormalizado,
  horarioSolicitadoDisponivel,
  motivoIndisponivel
}];

const agenda = $node["Definir Agenda"].json;
const eventosRaw = $items("Obter Eventos do Google Calendar").map(item => item.json);

const tz = agenda.timezone || "America/Sao_Paulo";
const intervaloMin = agenda.timeBetweenMeetingsMinutes;
const nomesDia = ["DOM", "SEG", "TER", "QUA", "QUI", "SEX", "SAB"];

const leadEmail = ($('trigger').first().json.email || "").trim().toLowerCase();

// Quantos dias corridos varrer
const DIAS_A_FRENTE = 14;
// Máximo de slots devolvidos (0 = sem limite)
const MAX_SLOTS = 6;

// Normaliza eventos: pega só YYYY-MM-DDTHH:MM do dateTime de SP
const eventos = (eventosRaw || [])
  .filter(ev => ev?.start?.dateTime && ev?.end?.dateTime)
  .filter(ev => !(ev.attendees || []).some(a => (a.email || "").trim().toLowerCase() === leadEmail))
  .map(ev => ({
    start: ev.start.dateTime.substring(0, 16),
    end:   ev.end.dateTime.substring(0, 16),
  }));

// "Hoje" em SP
const hojeStr = new Date().toLocaleString("sv-SE", { timeZone: tz }).slice(0, 10);
const agoraSP = new Date().toLocaleString("sv-SE", { timeZone: tz }).slice(11, 16); // "HH:MM"

// Data a partir de hoje + N dias, em SP
function getDataOffset(dias) {
  const d = new Date(hojeStr + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + dias);
  return d.toISOString().slice(0, 10); // "YYYY-MM-DD"
}

function nomeDiaDaData(dataStr) {
  return nomesDia[new Date(dataStr + "T00:00:00Z").getUTCDay()];
}

// Soma minutos em "HH:MM"
function somaMinutos(hhmm, min) {
  const [h, m] = hhmm.split(":").map(Number);
  const total = h * 60 + m + min;
  return String(Math.floor(total / 60)).padStart(2, "0") + ":" + String(total % 60).padStart(2, "0");
}

// Compara "HH:MM" como string
function menorQue(a, b) {
  return a < b;
}

let slotsLivres = [];

for (let i = 0; i < DIAS_A_FRENTE; i++) {
  const dataStr = getDataOffset(i);
  const nomeDia = nomeDiaDaData(dataStr);
  const dia = agenda.schedule.find(d => d.day === nomeDia);

  if (!dia || !dia.available) continue;

  const faixas = Array.isArray(dia.hours) ? dia.hours : [dia.hours];

  for (const faixa of faixas) {
    if (!faixa || !faixa.after || !faixa.before) continue;

    let current = faixa.after;   // "HH:MM"
    const fim   = faixa.before;  // "HH:MM"

    while (menorQue(current, fim)) {
      const next = somaMinutos(current, intervaloMin);
      if (next > fim) break;

      const currentDT = `${dataStr}T${current}`; // "YYYY-MM-DDTHH:MM"
      const nextDT    = `${dataStr}T${next}`;

      // Bloqueia slots passados de hoje (+ 30 min de margem)
      if (dataStr === hojeStr) {
        const limite = somaMinutos(agoraSP, 30);
        if (menorQue(current, limite)) {
          current = next;
          continue;
        }
      }

      // Checa conflito: compara strings "YYYY-MM-DDTHH:MM" diretamente
      const ocupado = eventos.some(ev => currentDT < ev.end && nextDT > ev.start);

      if (!ocupado) {
        slotsLivres.push({
          day:   nomeDia,
          date:  dataStr,
          start: currentDT,  // "2026-09-09T11:00" — SP, sem Z, sem conversão
          end:   nextDT,
        });
      }

      current = next;
    }
  }
}

// Ordena por data/hora real
slotsLivres.sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

if (MAX_SLOTS > 0) {
  slotsLivres = slotsLivres.slice(0, MAX_SLOTS);
}

return slotsLivres;

// ===============================
// INPUT
// ===============================
const input = $items("trigger")[0].json;
const { dia, horario, nome, empresa, email, telefone, descricao } = input;

const tz = "America/Sao_Paulo";

// ===============================
// DATA ATUAL EM SP
// ===============================
const agora = new Date().toLocaleString("sv-SE", { timeZone: tz });
const hojeStr = agora.slice(0, 10);
const agoraSP = agora.slice(11, 16);

function somaMinutos(hhmm, min) {
  const [h, m] = hhmm.split(":").map(Number);
  const total = h * 60 + m + min;
  return String(Math.floor(total / 60)).padStart(2, "0") + ":" +
         String(total % 60).padStart(2, "0");
}

const limite = somaMinutos(agoraSP, 30);

// ===============================
// PEGAR TODOS OS SLOTS (FORMATO REAL)
// ===============================
const slotsBase = $items("Gerar Slots Livres").map(item => item.json);

if (!slotsBase.length) {
  throw new Error("Nenhum slot retornado pelo node 'Gerar Slots Livres'.");
}

// ===============================
// FILTRAR PASSADO E < 30 MIN
// ===============================
const slots = slotsBase.filter(slot => {
  const slotDia  = slot.start.slice(0, 10);
  const slotHora = slot.start.slice(11, 16);

  if (slotDia === hojeStr) return slotHora >= limite;
  return slotDia > hojeStr;
});

// ===============================
// VERIFICAR HORÁRIO SOLICITADO
// ===============================
function normalizaHora(texto) {
  if (!texto) return null;
  const t = String(texto).trim().toLowerCase();
  let m = t.match(/^(\d{1,2}):(\d{2})$/);
  if (m) return String(m[1]).padStart(2, "0") + ":" + m[2];
  m = t.match(/^(\d{1,2})\s*h\s*(\d{2})?$/);
  if (m) return String(m[1]).padStart(2, "0") + ":" + (m[2] || "00");
  m = t.match(/^(\d{1,2})$/);
  if (m && Number(m[1]) <= 23) return String(m[1]).padStart(2, "0") + ":00";
  return null;
}

let solicitadoKey = null;

if (horario && String(horario).includes("T")) {
  const bruto = String(horario).slice(0, 16);
  const h = normalizaHora(bruto.slice(11));
  if (h) solicitadoKey = bruto.slice(0, 10) + "T" + h;
} else if (dia) {
  const h = normalizaHora(horario);
  if (h) solicitadoKey = `${dia}T${h}`;
}

const encontrado = solicitadoKey
  ? slots.find(slot => slot.start === solicitadoKey)
  : null;

// ===============================
// RETORNO DISPONÍVEL (novo bloco)
// ===============================
if (encontrado) {
  return [{
    json: {
      status: "disponivel",
      message: `Horário ${dia} ${horario} confirmado.`,
      slot: encontrado
    }
  }];
}

// ===============================
// AGRUPAR POR DIA
// ===============================
const slotsPorDia = {};

for (const slot of slots) {
  const d = slot.start.slice(0, 10);
  if (!slotsPorDia[d]) slotsPorDia[d] = [];
  slotsPorDia[d].push(slot);
}

for (const d in slotsPorDia) {
  slotsPorDia[d].sort((a, b) => a.start.localeCompare(b.start));
}

// ===============================
// FUNÇÃO PARA SOMAR DIAS
// ===============================
function addDias(dataStr, n) {
  const d = new Date(dataStr + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

// ===============================
// BUSCAR ALTERNATIVAS
// ===============================
let alternativas = [];

const prev = addDias(dia, -1);
const next = addDias(dia, +1);

alternativas.push(...(slotsPorDia[prev]?.slice(0, 2) || []));
alternativas.push(...(slotsPorDia[dia]?.slice(0, 2)  || []));
alternativas.push(...(slotsPorDia[next]?.slice(0, 2) || []));

let offset = 2;

while (alternativas.length < 2 && offset <= 7) {
  alternativas.push(...(slotsPorDia[addDias(dia, -offset)]?.slice(0, 2) || []));
  alternativas.push(...(slotsPorDia[addDias(dia, +offset)]?.slice(0, 2) || []));
  offset++;
}

alternativas = alternativas
  .slice(0, 6)
  .map(slot => ({
    inicio: { dateTime: `${slot.start}:00`, timeZone: tz },
    fim:    { dateTime: `${slot.end}:00`,   timeZone: tz }
  }));

// ===============================
// RETORNO INDISPONÍVEL
// ===============================
return [{
  json: {
    status: "indisponivel",
    message: solicitadoKey
      ? `O horário ${dia} ${horario} não está disponível.`
      : `Não consegui identificar o horário solicitado ("${horario}"). Segue disponibilidade.`,
    alternativas
  }
}];

const leadEmail = $('trigger').first().json.email ? $('trigger').first().json.email.trim().toLowerCase() : '';
const now = new Date();

// 1. Filtra eventos onde o lead está presente
const matches = items.filter(item => {
  const event = item.json;
  if (event.attendees && Array.isArray(event.attendees)) {
    return event.attendees.some(attendee => 
      attendee.email && attendee.email.trim().toLowerCase() === leadEmail
    );
  }
  return false;
});

// 2. Filtra apenas eventos futuros e ordena por data
const futureMeetings = matches
  .filter(item => new Date(item.json.start.dateTime) > now) // Apenas datas futuras
  .sort((a, b) => new Date(a.json.start.dateTime) - new Date(b.json.start.dateTime)); // Ordena do mais próximo para o mais distante

// Retorna a reunião futura mais próxima. Se não houver futura, retorna a última encontrada.
return futureMeetings.length > 0 ? [futureMeetings[0]] : matches;

const TIMEZONE = "America/Sao_Paulo";

const leadEmailRaw = $('trigger').first().json.email; 

if (!leadEmailRaw) {
    return [{ json: { error: "Dados incompletos", found: false } }];
}

const leadEmail = leadEmailRaw.trim().toLowerCase();

// Use UTC mesmo (mais seguro)
const now = new Date();

// Função pra pegar dateTime com fallback (caso seja all-day)
function getEventDate(item) {
  const start = item.json.start;
  if (!start) return null;

  // Eventos com hora
  if (start.dateTime) return new Date(start.dateTime);

  // Eventos all-day (date)
  if (start.date) return new Date(start.date + "T00:00:00");

  return null;
}

// Filtra eventos do lead
const matches = items.filter(item => {
  const event = item.json;

  return event.attendees?.some(attendee =>
    attendee.email?.trim().toLowerCase() === leadEmail
  );
});

// Separa eventos futuros e passados
const futureMeetings = matches
  .map(item => ({ item, date: getEventDate(item) }))
  .filter(e => e.date && e.date >= now)
  .sort((a, b) => a.date - b.date);

const pastMeetings = matches
  .map(item => ({ item, date: getEventDate(item) }))
  .filter(e => e.date && e.date < now)
  .sort((a, b) => b.date - a.date);

// Pega os candidatos
const nextMeeting = futureMeetings[0] || null;
const lastMeeting = pastMeetings[0] || null;

// Formatação correta com timezone
function formatDateTime(date) {
  return {
    date: date.toLocaleDateString("pt-BR", {
      timeZone: TIMEZONE
    }),
    time: date.toLocaleTimeString("pt-BR", {
      timeZone: TIMEZONE,
      hour: '2-digit',
      minute: '2-digit'
    })
  };
}

return [{
  json: {
    found: !!(nextMeeting || lastMeeting),

    nextMeeting: nextMeeting ? {
      eventId: nextMeeting.item.json.id,
      summary: nextMeeting.item.json.summary,
      ...formatDateTime(nextMeeting.date)
    } : null,

    lastMeeting: lastMeeting ? {
      eventId: lastMeeting.item.json.id,
      summary: lastMeeting.item.json.summary,
      ...formatDateTime(lastMeeting.date)
    } : null
  }
}];

const TIMEZONE_OFFSET = '-03:00'; 
const MEETING_DURATION_MINUTES = 30;

const leadEmailRaw = $('trigger').first().json.email; 
const newDateStr = $('trigger').first().json.dia;
const newTimeStr = $('trigger').first().json.horario;

if (!leadEmailRaw || !newDateStr || !newTimeStr) {
    return [{ json: { error: "Dados incompletos", found: false } }];
}

const leadEmail = leadEmailRaw.trim().toLowerCase();
const nowBrasil = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));

// Busca os eventos explicitamente pelo node, em vez de depender do input implícito
// (esse node agora vem depois da checagem de disponibilidade, então "items" não são
// mais os eventos do Google Calendar)
const eventos = $items("Obter Eventos do Google Calendar2").map(e => e.json);

const matches = eventos.filter(event => {
  if (event.attendees && Array.isArray(event.attendees)) {
    return event.attendees.some(attendee => 
      attendee.email && attendee.email.trim().toLowerCase() === leadEmail
    );
  }
  return false;
});

// Pega o mais próximo de hoje, passado ou futuro
const meetingsSorted = matches
  .filter(event => event.start && event.start.dateTime)
  .sort((a, b) => {
    const diffA = Math.abs(new Date(a.start.dateTime) - nowBrasil);
    const diffB = Math.abs(new Date(b.start.dateTime) - nowBrasil);
    return diffA - diffB;
  });

if (meetingsSorted.length === 0) {
    return [{ json: { error: "Nenhuma reunião encontrada para reagendar.", found: false } }];
}

const meetingToReschedule = meetingsSorted[0];

const isoStringBrasil = `${newDateStr}T${newTimeStr}:00${TIMEZONE_OFFSET}`;
const startDate = new Date(isoStringBrasil);
const endDate = new Date(startDate.getTime() + MEETING_DURATION_MINUTES * 60000);

return [{
    json: {
        found: true,
        eventId: meetingToReschedule.id,
        calendarId: "primary",
        summary: meetingToReschedule.summary,
        updatePayload: {
            start: {
                dateTime: startDate.toISOString(), 
                timeZone: "America/Sao_Paulo"
            },
            end: {
                dateTime: endDate.toISOString(),
                timeZone: "America/Sao_Paulo"
            }
        },
        debug_check: `Entrada: ${isoStringBrasil} -> Gerado UTC: ${startDate.toISOString()}`
    }
}];

const TIMEZONE_OFFSET = '-03:00';
const MEETING_DURATION_MINUTES = 30;

const leadEmailRaw = $('trigger').first().json.email;
const newDateStr = $('trigger').first().json.dia;
const newTimeStr = $('trigger').first().json.horario;

const eventos = $items("Obter Eventos do Google Calendar").map(e => e.json);

if (!leadEmailRaw || !newDateStr || !newTimeStr) {
  return [{ json: { error: "Dados incompletos" } }];
}

const leadEmail = leadEmailRaw.trim().toLowerCase();

const nowBrasil = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));

// ===========================================================
// 1️⃣ FILTRAR EVENTOS DO LEAD
// ===========================================================
const matches = eventos.filter(event => {
  if (!event.attendees) return false;
  return event.attendees.some(att =>
    att.email && att.email.trim().toLowerCase() === leadEmail
  );
});

// Pega a mais próxima de hoje, passada ou futura
const meetingsSorted = matches
  .filter(ev => ev.start.dateTime)
  .sort((a, b) => {
    const diffA = Math.abs(new Date(a.start.dateTime) - nowBrasil);
    const diffB = Math.abs(new Date(b.start.dateTime) - nowBrasil);
    return diffA - diffB; // menor diferença primeiro
  });

// ===========================================================
// 2️⃣ DEFINIR SE É REAGENDAMENTO
// ===========================================================
let isReschedule = false;
let meetingToReschedule = null;

if (meetingsSorted.length > 0) {
  isReschedule = true;
  meetingToReschedule = meetingsSorted[0];
}

// ===========================================================
// 3️⃣ CALCULAR NOVO HORÁRIO
// ===========================================================
const isoStringBrasil = `${newDateStr}T${newTimeStr}:00${TIMEZONE_OFFSET}`;
const startDate = new Date(isoStringBrasil);
const endDate = new Date(startDate.getTime() + MEETING_DURATION_MINUTES * 60000);

// ===========================================================
// 4️⃣ RETORNO
// ===========================================================
return [{
  json: {
    input: $input.all(),
    isReschedule,
    eventId: meetingToReschedule ? meetingToReschedule.id : null,
    summary: meetingToReschedule ? meetingToReschedule.summary : null,
    payload: {
      start: {
        dateTime: startDate.toISOString(),
        timeZone: "America/Sao_Paulo"
      },
      end: {
        dateTime: endDate.toISOString(),
        timeZone: "America/Sao_Paulo"
      }
    },
    debug: {
      entrada: isoStringBrasil,
      startUTC: startDate.toISOString(),
      leadEmail
    }
  }
}];

